{
  "name": "crates_io",
  "manual_version": "1.0.0",
  "utcp_version": "1.0.1",
  "tools": [
    {
      "name": "get_crate_info",
      "description": "Získá metadata a závislosti Rust crate z crates.io",
      "inputs": {
        "type": "object",
        "properties": {
          "crate_name": { "type": "string", "description": "Název crate" }
        },
        "required": ["crate_name"]
      },
      "tool_call_template": {
        "call_template_type": "http",
        "url": "https://crates.io/api/v1/crates/${crate_name}",
        "http_method": "GET",
        "headers": { "User-Agent": "utcp-agent (macOS-arm64)" }
      }
    }
  ]
}

{
  "name": "pypi_api",
  "manual_version": "1.0.0",
  "utcp_version": "1.0.1",
  "tools": [
    {
      "name": "get_package_metadata",
      "description": "Vrátí metadata Python balíčku z PyPI",
      "inputs": {
        "type": "object",
        "properties": {
          "package_name": { "type": "string", "description": "Název balíčku" }
        },
        "required": ["package_name"]
      },
      "tool_call_template": {
        "call_template_type": "http",
        "url": "https://pypi.org/pypi/${package_name}/json",
        "http_method": "GET",
        "headers": { "User-Agent": "utcp-agent (macOS-arm64)" }
      }
    }
  ]
}

{
  "name": "bash_manual",
  "manual_version": "1.0.0",
  "utcp_version": "1.0.1",
  "tools": [
    {
      "name": "bash",
      "description": "Execute bash commands on macOS. Returns command output.",
      "inputs": {
        "type": "object",
        "properties": {
          "command": { "type": "string", "description": "bash command to execute" },
          "workdir": { "type": "string", "description": "Working directory (optional)" },
          "timeout": { "type": "number", "description": "Timeout in seconds (default 120)" }
        },
        "required": ["command"]
      },
      "tool_call_template": {
        "call_template_type": "cli",
        "command": "bash",
        "args": ["-c", "${command}"]
      }
    }
  ]
}

{
  "name": "glob_manual",
  "manual_version": "1.0.0",
  "utcp_version": "1.0.1",
  "tools": [
    {
      "name": "glob",
      "description": "Find files by glob pattern. Respects .gitignore.",
      "inputs": {
        "type": "object",
        "properties": {
          "pattern": { "type": "string", "description": "Glob pattern (e.g. **/*.py, src/**/*.ts)" },
          "path": { "type": "string", "description": "Directory to search in (default: cwd)" }
        },
        "required": ["pattern"]
      },
      "tool_call_template": {
        "call_template_type": "cli",
        "command": "find",
        "args": ["${path:-.}", "-name", "${pattern}"]
      }
    }
  ]
}

{
  "name": "grep_manual",
  "manual_version": "1.0.0",
  "utcp_version": "1.0.1",
  "tools": [
    {
      "name": "grep",
      "description": "Search file contents using regex pattern",
      "inputs": {
        "type": "object",
        "properties": {
          "pattern": { "type": "string", "description": "Regex pattern to search" },
          "path": { "type": "string", "description": "Directory or file to search in" },
          "include": { "type": "string", "description": "File glob filter (e.g. *.py)" }
        },
        "required": ["pattern", "path"]
      },
      "tool_call_template": {
        "call_template_type": "cli",
        "command": "grep",
        "args": ["-rn", "${pattern}", "${path}", "--include=${include:-*}"]
      }
    }
  ]
}

{
  "name": "read_file_manual",
  "manual_version": "1.0.0",
  "utcp_version": "1.0.1",
  "tools": [
    {
      "name": "read_file",
      "description": "Read file contents with line offset and limit",
      "inputs": {
        "type": "object",
        "properties": {
          "path": { "type": "string", "description": "Absolute file path" },
          "offset": { "type": "number", "description": "Line offset (1-indexed, default 1)" },
          "limit": { "type": "number", "description": "Max lines to read (default 0 = all)" }
        },
        "required": ["path"]
      },
      "tool_call_template": {
        "call_template_type": "cli",
        "command": "sed",
        "args": ["-n", "${offset:-1},${limit:-}p", "${path}"]
      }
    }
  ]
}

{
  "name": "write_file_manual",
  "manual_version": "1.0.0",
  "utcp_version": "1.0.1",
  "tools": [
    {
      "name": "write_file",
      "description": "Write content to a file, creating or overwriting it",
      "inputs": {
        "type": "object",
        "properties": {
          "path": { "type": "string", "description": "Absolute file path" },
          "content": { "type": "string", "description": "File content to write" }
        },
        "required": ["path", "content"]
      },
      "tool_call_template": {
        "call_template_type": "cli",
        "command": "tee",
        "args": ["${path}"]
      }
    }
  ]
}

{
  "name": "list_dir_manual",
  "manual_version": "1.0.0",
  "utcp_version": "1.0.1",
  "tools": [
    {
      "name": "list_dir",
      "description": "List directory contents alphabetically",
      "inputs": {
        "type": "object",
        "properties": {
          "path": { "type": "string", "description": "Directory path" }
        },
        "required": ["path"]
      },
      "tool_call_template": {
        "call_template_type": "cli",
        "command": "ls",
        "args": ["-1", "${path}"]
      }
    }
  ]
}

{
  "name": "web_fetch_manual",
  "manual_version": "1.0.0",
  "utcp_version": "1.0.1",
  "tools": [
    {
      "name": "web_fetch",
      "description": "Fetch URL content with format conversion (markdown/text/html)",
      "inputs": {
        "type": "object",
        "properties": {
          "url": { "type": "string", "description": "URL to fetch" },
          "format": { "type": "string", "description": "Output format: markdown, text, or html", "enum": ["markdown", "text", "html"] },
          "timeout": { "type": "number", "description": "Timeout in seconds (default 30, max 120)" }
        },
        "required": ["url"]
      },
      "tool_call_template": {
        "call_template_type": "http",
        "url": "${url}",
        "http_method": "GET",
        "headers": { "User-Agent": "UTCP-Agent/1.0 (macOS-arm64)" }
      }
    }
  ]
}

{
  "name": "pytest_manual",
  "manual_version": "1.0.0",
  "utcp_version": "1.0.1",
  "tools": [
    {
      "name": "pytest",
      "description": "Run pytest with options. Use --timeout=30 -q for fast testing.",
      "inputs": {
        "type": "object",
        "properties": {
          "path": { "type": "string", "description": "Test path or directory (default: tests/)" },
          "args": { "type": "string", "description": "pytest arguments (e.g. -x --timeout=30)" }
        }
      },
      "tool_call_template": {
        "call_template_type": "cli",
        "command": "pytest",
        "args": ["${path:-tests/}", "${args:- -x --timeout=30 -q}"]
      }
    }
  ]
}

{
  "name": "ruff_check_manual",
  "manual_version": "1.0.0",
  "utcp_version": "1.0.1",
  "tools": [
    {
      "name": "ruff_check",
      "description": "Run ruff linter with optional auto-fix",
      "inputs": {
        "type": "object",
        "properties": {
          "path": { "type": "string", "description": "Path to lint (file or directory)" },
          "fix": { "type": "boolean", "description": "Auto-fix issues if true" }
        },
        "required": ["path"]
      },
      "tool_call_template": {
        "call_template_type": "cli",
        "command": "ruff",
        "args": ["check", "${path}", "${fix:--fix}"]
      }
    }
  ]
}

{
  "name": "ruff_format_manual",
  "manual_version": "1.0.0",
  "utcp_version": "1.0.1",
  "tools": [
    {
      "name": "ruff_format",
      "description": "Format Python files with ruff",
      "inputs": {
        "type": "object",
        "properties": {
          "path": { "type": "string", "description": "File or directory to format" },
          "check": { "type": "boolean", "description": "Check only, don't write (default false)" }
        },
        "required": ["path"]
      },
      "tool_call_template": {
        "call_template_type": "cli",
        "command": "ruff",
        "args": ["format", "${path}", "${check:--check}"]
      }
    }
  ]
}

{
  "name": "uv_sync_manual",
  "manual_version": "1.0.0",
  "utcp_version": "1.0.1",
  "tools": [
    {
      "name": "uv_sync",
      "description": "Sync dependencies with uv package manager",
      "inputs": {
        "type": "object",
        "properties": {
          "extra": { "type": "string", "description": "Extra dependencies to include (e.g. mlx-embed)" }
        }
      },
      "tool_call_template": {
        "call_template_type": "cli",
        "command": "uv",
        "args": ["sync", "${extra:+--extra}", "${extra:-}"]
      }
    }
  ]
}

{
  "name": "uv_add_manual",
  "manual_version": "1.0.0",
  "utcp_version": "1.0.1",
  "tools": [
    {
      "name": "uv_add",
      "description": "Add dependency with uv package manager",
      "inputs": {
        "type": "object",
        "properties": {
          "package": { "type": "string", "description": "Package name (e.g. requests>=2.28)" },
          "dev": { "type": "boolean", "description": "Add as dev dependency (default false)" }
