        "required": ["package"]
      },
      "tool_call_template": {
        "call_template_type": "cli",
        "command": "uv",
        "args": ["add", "${package}", "${dev:+--dev}"]
      }
    }
  ]
}

{
  "name": "git_manual",
  "manual_version": "1.0.0",
  "utcp_version": "1.0.1",
