{
  "name": "tmux_manual",
  "manual_version": "1.0.0",
  "utcp_version": "1.0.1",
  "tools": [
    {
      "name": "tmux_sessions",
      "description": "List all tmux sessions",
      "inputs": {
        "type": "object",
        "properties": {}
      },
