}

{
  "name": "fd_manual",
  "manual_version": "1.0.0",
  "utcp_version": "1.0.1",
  "tools": [
    {
      "name": "fd_find",
      "description": "Fast find alternative - find files by pattern",
      "inputs": {
        "type": "object",
        "properties": {
          "pattern": { "type": "string", "description": "Search pattern" },
          "path": { "type": "string", "description": "Directory to search" },
          "extension": { "type": "string", "description": "Filter by extension (e.g. .py)" }
        },
        "required": ["pattern"]
      },
      "tool_call_template": {
        "call_template_type": "cli",
        "command": "fd",
        "args": ["${pattern}", "${path:-.}", "${extension:+-e}", "${extension:-}"]
      }
    }
  ]
}

{
  "name": "bat_manual",
  "manual_version": "1.0.0",
  "utcp_version": "1.0.1",
  "tools": [
    {
      "name": "bat_view",
      "description": "Cat alternative with syntax highlighting",
      "inputs": {
        "type": "object",
        "properties": {
          "path": { "type": "string", "description": "File to view" },
          "language": { "type": "string", "description": "Force language" }
        },
        "required": ["path"]
      },
      "tool_call_template": {
        "call_template_type": "cli",
        "command": "bat",
        "args": ["${path}", "${language:+--language=}", "${language:-}"]
      }
    }
  ]
}

{
  "name": "exa_manual",
  "manual_version": "1.0.0",
  "utcp_version": "1.0.1",
  "tools": [
    {
      "name": "exa_list",
      "description": "Modern ls replacement with colors and icons",
      "inputs": {
        "type": "object",
        "properties": {
          "path": { "type": "string", "description": "Directory to list" },
          "long": { "type": "boolean", "description": "Long format" },
          "recursive": { "type": "boolean", "description": "Recursive listing" }
        }
      },
      "tool_call_template": {
        "call_template_type": "cli",
        "command": "exa",
        "args": ["${path:-.}", "${long:+-l}", "${recursive:+-R}"]
      }
    }
  ]
}

{
  "name": "fzf_manual",
  "manual_version": "1.0.0",
  "utcp_version": "1.0.1",
  "tools": [
    {
      "name": "fzf_files",
      "description": "Fuzzy file finder",
      "inputs": {
        "type": "object",
        "properties": {
          "path": { "type": "string", "description": "Directory to search" },
          "query": { "type": "string", "description": "Initial query" }
        }
      },
      "tool_call_template": {
        "call_template_type": "cli",
        "command": "fzf",
        "args": ["--query=${query:-}", "${path:-}"]
      }
    }
  ]
}

{
  "name": "gh_manual",
  "manual_version": "1.0.0",
  "utcp_version": "1.0.1",
  "tools": [
    {
      "name": "gh_issue_list",
      "description": "List GitHub issues",
      "inputs": {
        "type": "object",
        "properties": {
          "repo": { "type": "string", "description": "Repository (owner/repo)" },
          "state": { "type": "string", "description": "Filter: open, closed, all" },
          "limit": { "type": "number", "description": "Max results" }
        },
        "required": ["repo"]
      },
      "tool_call_template": {
        "call_template_type": "cli",
        "command": "gh",
        "args": ["issue", "list", "-R", "${repo}", "--state=${state:-open}", "-L", "${limit:-50}"]
      }
    }
  ]
}

